import { badRequest } from '../../core/errors.ts';
import { INGEST_TYPES, type IngestEvent } from '../../../shared/events.ts';

const MAX_EVENTS = 500;

/** A run id is generated by us; anything else in the URL is not a run and never reaches the filesystem. */
export const RUN_ID = /^[\w-]{1,64}$/;

/** The reporter's batch, checked for shape before the reducer trusts it. Events come from the run's own process, so this guards against mistakes, not attackers. */
export function parseIngestEvents(raw: unknown): IngestEvent[] {
  if (!Array.isArray(raw)) throw badRequest('Body must be an array of events');
  if (raw.length > MAX_EVENTS) throw badRequest(`At most ${MAX_EVENTS} events per request`);
  const known = new Set<string>(INGEST_TYPES);
  for (const e of raw) {
    if (typeof e !== 'object' || e === null || typeof (e as { type?: unknown }).type !== 'string' || !known.has((e as { type: string }).type)) throw badRequest('Unknown event type');
  }
  return raw as IngestEvent[];
}
